CREATE MATERIALIZED VIEW mv_popular_posts_30days AS ...;
CREATE INDEX idx_mv_posts_engagement ON mv_popular_posts_30days(engagement_score DESC);
REFRESH MATERIALIZED VIEW mv_popular_posts_30days;

-- WRONG: Create MV, refresh, then index (very slow!)
CREATE MATERIALIZED VIEW mv_stats AS SELECT ...;
REFRESH MATERIALIZED VIEW mv_stats;  -- Loads millions of rows
CREATE INDEX idx_mv_date ON mv_stats(date);  -- Takes 10+ minutes!

-- CORRECT: Create MV, index empty table, then refresh
CREATE MATERIALIZED VIEW mv_stats AS SELECT ...;
CREATE INDEX idx_mv_date ON mv_stats(date);  -- Takes 1 second!
REFRESH MATERIALIZED VIEW mv_stats;

-- Step 1: Create unique index (what makes each row unique?)
CREATE UNIQUE INDEX idx_mv_article_unique 
ON mv_article_stats(author_id, category, week);

-- Step 2: Use concurrent refresh
REFRESH MATERIALIZED VIEW CONCURRENTLY mv_article_stats;

CREATE EXTENSION IF NOT EXISTS pg_cron;
SELECT cron.schedule(
    'refresh-mv',
    '0 * * * *',  -- Every hour
    $$REFRESH MATERIALIZED VIEW CONCURRENTLY mv_article_stats$$
);

CREATE OR REPLACE FUNCTION refresh_mv_safely()
RETURNS void AS $$
BEGIN
    IF pg_try_advisory_lock(12345) THEN
        BEGIN
            REFRESH MATERIALIZED VIEW CONCURRENTLY mv_article_stats;
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE 'Refresh failed: %', SQLERRM;
        END;
        PERFORM pg_advisory_unlock(12345);
    ELSE
        RAISE NOTICE 'Refresh already in progress, skipping';
    END IF;
END;
$$ LANGUAGE plpgsql;

-- Update statistics
ANALYZE articles;
ANALYZE article_views;

-- Clean up bloat
VACUUM ANALYZE articles;

-- Check for bloat
SELECT * FROM pg_stat_user_tables WHERE n_dead_tup > 1000;

CREATE TABLE mv_refresh_log (
    mv_name TEXT,
    refresh_start TIMESTAMP,
    refresh_end TIMESTAMP,
    duration INTERVAL,
    rows_refreshed BIGINT
);

CREATE OR REPLACE FUNCTION refresh_mv_with_logging(mv_name TEXT)
RETURNS void AS $$
DECLARE
    start_time TIMESTAMP := NOW();
    end_time TIMESTAMP;
    row_count BIGINT;
BEGIN
    EXECUTE format('REFRESH MATERIALIZED VIEW CONCURRENTLY %I', mv_name);
    end_time := NOW();
    EXECUTE format('SELECT COUNT(*) FROM %I', mv_name) INTO row_count;
    INSERT INTO mv_refresh_log VALUES (mv_name, start_time, end_time, 
        end_time - start_time, row_count);
END;
$$ LANGUAGE plpgsql;

EXPLAIN ANALYZE SELECT * FROM mv_stats WHERE author_id = 123;
-- If you see "Seq Scan", add an index:
CREATE INDEX idx_mv_author ON mv_stats(author_id);

-- Identify what makes each row unique
CREATE UNIQUE INDEX idx_mv_unique 
ON mv_stats(author_id, category, week);

CREATE MATERIALIZED VIEW mv_author_performance AS ...;
CREATE UNIQUE INDEX idx_mv_author_unique ON mv_author_performance(author_id, category, week);
CREATE INDEX idx_mv_author_week ON mv_author_performance(author_id, week);
CREATE INDEX idx_mv_author_views ON mv_author_performance(total_views DESC);
REFRESH MATERIALIZED VIEW CONCURRENTLY mv_author_performance;

CREATE TABLE mv_refresh_metadata (
    mv_name TEXT PRIMARY KEY,
    last_refresh_at TIMESTAMP,
    refresh_duration INTERVAL,
    rows_count BIGINT
);

CREATE OR REPLACE FUNCTION refresh_mv_with_metadata(mv_name TEXT)
RETURNS void AS $$
DECLARE
    start_time TIMESTAMP := NOW();
    end_time TIMESTAMP;
    row_count BIGINT;
BEGIN
    EXECUTE format('REFRESH MATERIALIZED VIEW CONCURRENTLY %I', mv_name);
    end_time := NOW();
    EXECUTE format('SELECT COUNT(*) FROM %I', mv_name) INTO row_count;
    INSERT INTO mv_refresh_metadata VALUES 
        (mv_name, end_time, end_time - start_time, row_count)
    ON CONFLICT (mv_name) DO UPDATE SET
        last_refresh_at = EXCLUDED.last_refresh_at,
        refresh_duration = EXCLUDED.refresh_duration,
        rows_count = EXCLUDED.rows_count;
END;
$$ LANGUAGE plpgsql;
